"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Textarea } from "@/components/ui/textarea";
import { Input } from "@/components/ui/input";
import { Skeleton } from "@/components/ui/skeleton";
import { 
  Bot, Mic, Brain, Volume2, Phone, ArrowLeft, Save, RefreshCw,
  Play, CheckCircle2, Settings2, MessageSquare
} from "lucide-react";
import { useRouter } from "next/navigation";
import { toast } from "sonner";
import { Switch } from "@/components/ui/switch";
import api from "@/lib/api";

// Default Models
const DEFAULT_STT_MODELS = [
  { value: "deepgram/nova-3", label: "Deepgram Nova 3", description: "Best accuracy" },
  { value: "deepgram/nova-2", label: "Deepgram Nova 2", description: "Great accuracy" },
];

const DEFAULT_LLM_MODELS = [
  { value: "groq/llama-3.3-70b-versatile", label: "Llama 3.3 70B (Groq)", description: "Ultra fast" },
  { value: "openai/gpt-4o-mini", label: "GPT-4o Mini", description: "Cost-effective" },
];

const DEFAULT_TTS_VOICES = [
  { value: "79a125e8-cd45-4c13-8a67-188112f4dd22", label: "Sarah (Cartesia)", description: "Female, Professional" },
  { value: "EXAVITQu4vr4xnSDxMaL", label: "Sarah (ElevenLabs)", description: "Female, American" },
];

interface AgentConfig {
  name: string;
  system_prompt: string;
  first_message: string;
  llm_model: string;
  stt_model: string;
  voice_id: string;
  voice_provider: string;
  tools_config: {
    check_availability: boolean;
    book_appointment: boolean;
    cancel_appointment: boolean;
    get_business_info: boolean;
  };
}

interface ModelOption {
  value: string;
  label: string;
  description?: string;
  provider?: string;
}

export default function AISettingsPage() {
  const router = useRouter();
  
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [lastSaved, setLastSaved] = useState<Date | null>(null);
  const [hasChanges, setHasChanges] = useState(false);
  const [previewingVoice, setPreviewingVoice] = useState(false);
  const [hasElevenLabsKey, setHasElevenLabsKey] = useState(false);
  const [startingCall, setStartingCall] = useState(false);
  const [activeTab, setActiveTab] = useState<"voice" | "brain" | "behavior" | "tools">("voice");
  
  // Dynamic Models
  const [sttModels] = useState<ModelOption[]>(DEFAULT_STT_MODELS);
  const [llmModels, setLlmModels] = useState<ModelOption[]>(DEFAULT_LLM_MODELS);
  const [ttsVoices, setTtsVoices] = useState<ModelOption[]>(DEFAULT_TTS_VOICES);

  const [config, setConfig] = useState<AgentConfig>({
    name: "AI Receptionist",
    system_prompt: "You are a friendly AI receptionist. Help customers book appointments and answer questions.",
    first_message: "Hello! I'm your AI receptionist. How can I help you today?",
    llm_model: "groq/llama-3.3-70b-versatile",
    stt_model: "deepgram/nova-3",
    voice_id: "79a125e8-cd45-4c13-8a67-188112f4dd22",
    voice_provider: "cartesia",
    tools_config: {
      check_availability: true,
      book_appointment: true,
      cancel_appointment: true,
      get_business_info: true,
    }
  });

  const saveTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  useEffect(() => {
    loadData();
  }, []);

  // Auto-save with debounce
  useEffect(() => {
    if (!loading && hasChanges) {
      if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current);
      saveTimeoutRef.current = setTimeout(() => autoSave(), 1500);
    }
    return () => { if (saveTimeoutRef.current) clearTimeout(saveTimeoutRef.current); };
  }, [config, hasChanges, loading]);

  const loadData = async () => {
    try {
      setLoading(true);
      
      // Fetch API Keys - api.get() returns data directly (not response.data)
      const apiKeys = await api.get("/keys") || [];
      console.log("API Keys:", apiKeys);
      
      const providers = (Array.isArray(apiKeys) ? apiKeys : []).map((k: any) => k.provider).filter(Boolean);
      console.log("Providers:", providers);
      setHasElevenLabsKey(providers.includes('elevenlabs'));

      // Fetch dynamic models/voices
      const promises: Promise<any>[] = [];
      
      if (providers.includes('groq')) {
        promises.push(
          api.get("/keys/groq/models")
            .then(data => ({ type: 'llm', provider: 'Groq', data }))
            .catch(e => { console.error("Groq error:", e); return null; })
        );
      }
      if (providers.includes('openai')) {
        promises.push(
          api.get("/keys/openai/models")
            .then(data => ({ type: 'llm', provider: 'OpenAI', data }))
            .catch(e => { console.error("OpenAI error:", e); return null; })
        );
      }
      if (providers.includes('elevenlabs')) {
        promises.push(
          api.get("/keys/elevenlabs/voices")
            .then(data => ({ type: 'voice', provider: 'ElevenLabs', data }))
            .catch(e => { console.error("ElevenLabs error:", e); return null; })
        );
      }
      if (providers.includes('cartesia')) {
        promises.push(
          api.get("/keys/cartesia/voices")
            .then(data => ({ type: 'voice', provider: 'Cartesia', data }))
            .catch(e => { console.error("Cartesia error:", e); return null; })
        );
      }

      const results = await Promise.all(promises);
      console.log("Results:", results);
      
      const newLlmModels = [...DEFAULT_LLM_MODELS];
      const newTtsVoices = [...DEFAULT_TTS_VOICES];

      results.forEach(r => {
        if (!r) return;
        
        if (r.type === 'llm') {
          const models = Array.isArray(r.data) ? r.data : [];
          console.log(`${r.provider} models:`, models.length);
          models.forEach((m: any) => {
            if (!newLlmModels.find(x => x.value === m.id)) {
              newLlmModels.push({ 
                value: m.id, 
                label: `${m.id} (${r.provider})`, 
                description: "Your API"
              });
            }
          });
        }
        
        if (r.type === 'voice') {
          const voices = Array.isArray(r.data) ? r.data : r.data?.voices || [];
          console.log(`${r.provider} voices:`, voices.length);
          voices.forEach((v: any) => {
            const voiceId = v.voice_id || v.id;
            if (!newTtsVoices.find(x => x.value === voiceId)) {
              newTtsVoices.push({ 
                value: voiceId, 
                label: `${v.name} (${r.provider})`, 
                description: v.labels?.accent || v.description
              });
            }
          });
        }
      });
      
      console.log("Final LLM Models:", newLlmModels.length);
      console.log("Final TTS Voices:", newTtsVoices.length);
      
      setLlmModels(newLlmModels);
      setTtsVoices(newTtsVoices);

      // Fetch current config
      try {
        const aiConfig = await api.get("/ai-config");
        if (aiConfig) {
          setConfig({
            name: aiConfig.name || "AI Receptionist",
            system_prompt: aiConfig.system_prompt || "",
            first_message: aiConfig.first_message || "Hello!",
            llm_model: aiConfig.llm_model || "groq/llama-3.3-70b-versatile",
            stt_model: aiConfig.stt_model || "deepgram/nova-3",
            voice_id: aiConfig.voice_id || DEFAULT_TTS_VOICES[0].value,
            voice_provider: aiConfig.voice_provider || "cartesia",
            tools_config: aiConfig.tools_config || config.tools_config,
          });
        }
      } catch (e) {
        console.log("Using defaults for config");
      }
    } catch (error) {
      console.error("Failed to load:", error);
      toast.error("Could not load all options");
    } finally {
      setLoading(false);
    }
  };

  const updateConfig = useCallback((updates: Partial<AgentConfig>) => {
    setConfig(prev => ({ ...prev, ...updates }));
    setHasChanges(true);
  }, []);

  const autoSave = async () => {
    setSaving(true);
    try {
      await api.put("/ai-config", config);
      setLastSaved(new Date());
      setHasChanges(false);
      toast.success("AI configuration saved!");
    } catch (error) {
      toast.error("Save failed");
    } finally {
      setSaving(false);
    }
  };

  const handleSave = async () => {
    setSaving(true);
    try {
      await api.put("/ai-config", config);
      setLastSaved(new Date());
      setHasChanges(false);
      toast.success("AI configuration saved!");
    } catch (error) {
      toast.error("Failed to save");
    } finally {
      setSaving(false);
    }
  };

  const previewVoice = async () => {
    if (!hasElevenLabsKey) {
      toast.info("Add ElevenLabs key for voice preview");
      return;
    }
    setPreviewingVoice(true);
    try {
      const response = await api.post(`/keys/elevenlabs/preview?voice_id=${config.voice_id}&text=${encodeURIComponent(config.first_message)}`, {}, { responseType: 'blob' });
      const audio = new Audio(URL.createObjectURL(response));
      audio.play();
    } catch (error) {
      toast.error("Preview failed");
    } finally {
      setPreviewingVoice(false);
    }
  };

  const startTestCall = async () => {
    setStartingCall(true);
    try {
      await api.put("/ai-config", config);
      router.push("/dashboard/voice-agent/test");
    } catch (error) {
      toast.error("Could not start call");
      setStartingCall(false);
    }
  };

  if (loading) {
    return (
      <div className="p-6">
        <div className="flex items-center gap-4 mb-6">
          <Skeleton className="w-10 h-10 rounded" />
          <div>
            <Skeleton className="h-8 w-48 mb-2" />
            <Skeleton className="h-4 w-64" />
          </div>
        </div>
        <div className="glass rounded-2xl p-6">
          <Skeleton className="h-20 w-full mb-4" />
          <Skeleton className="h-20 w-full mb-4" />
          <Skeleton className="h-32 w-full" />
        </div>
      </div>
    );
  }

  const tabs = [
    { id: "voice", label: "Voice", icon: Volume2 },
    { id: "brain", label: "Brain", icon: Brain },
    { id: "behavior", label: "Behavior", icon: MessageSquare },
    { id: "tools", label: "Tools", icon: Settings2 },
  ];

  return (
    <div className="p-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <Button variant="ghost" size="icon" onClick={() => router.push('/dashboard/settings')}>
            <ArrowLeft className="w-5 h-5" />
          </Button>
          <div>
            <h1 className="text-3xl font-bold mb-2">AI Configuration</h1>
            <p className="text-muted-foreground">
              Configure your AI receptionist's voice, brain, and behavior
            </p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          {lastSaved && (
            <span className="text-sm text-muted-foreground flex items-center gap-1">
              <CheckCircle2 className="w-4 h-4 text-green-500" />
              Saved {lastSaved.toLocaleTimeString()}
            </span>
          )}
          <Button
            className="gap-2 bg-gradient-to-r from-primary to-accent"
            onClick={handleSave}
            disabled={saving}
          >
            {saving ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Save className="w-4 h-4" />}
            Save Changes
          </Button>
        </div>
      </div>

      {/* Quick Actions */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
        <div className="glass rounded-2xl p-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-green-500 to-emerald-500 flex items-center justify-center">
                <Phone className="w-6 h-6 text-white" />
              </div>
              <div>
                <h3 className="font-semibold">Test Your AI</h3>
                <p className="text-sm text-muted-foreground">Start a live call</p>
              </div>
            </div>
            <Button onClick={startTestCall} disabled={startingCall} className="bg-gradient-to-r from-green-500 to-emerald-500">
              {startingCall ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Phone className="w-4 h-4 mr-2" />}
              Test Call
            </Button>
          </div>
        </div>

        <div className="glass rounded-2xl p-6">
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 rounded-xl bg-gradient-to-br from-purple-500 to-pink-500 flex items-center justify-center">
                <Volume2 className="w-6 h-6 text-white" />
              </div>
              <div>
                <h3 className="font-semibold">Preview Voice</h3>
                <p className="text-sm text-muted-foreground">Hear a sample</p>
              </div>
            </div>
            <Button variant="outline" onClick={previewVoice} disabled={previewingVoice}>
              {previewingVoice ? <RefreshCw className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4 mr-2" />}
              Play
            </Button>
          </div>
        </div>
      </div>

      {/* Tabs */}
      <div className="flex gap-2 mb-6">
        {tabs.map((tab) => (
          <button
            key={tab.id}
            onClick={() => setActiveTab(tab.id as any)}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all ${
              activeTab === tab.id 
                ? 'bg-primary text-primary-foreground' 
                : 'glass hover:bg-white/10'
            }`}
          >
            <tab.icon className="w-4 h-4" />
            {tab.label}
          </button>
        ))}
      </div>

      {/* Tab Content */}
      <div className="glass rounded-2xl p-6">
        {activeTab === "voice" && (
          <div className="space-y-6">
            <div>
              <Label className="text-base font-semibold">AI Voice</Label>
              <p className="text-sm text-muted-foreground mb-3">Choose the voice your AI uses</p>
              <Select 
                value={config.voice_id} 
                onValueChange={(value) => {
                  const voice = ttsVoices.find(v => v.value === value);
                  updateConfig({ voice_id: value, voice_provider: voice?.provider?.toLowerCase() || "cartesia" });
                }}
              >
                <SelectTrigger className="glass-strong">
                  <SelectValue placeholder="Select a voice" />
                </SelectTrigger>
                <SelectContent>
                  {ttsVoices.map((voice) => (
                    <SelectItem key={voice.value} value={voice.value}>
                      {voice.label} — {voice.description}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            <div>
              <Label className="text-base font-semibold">First Message</Label>
              <p className="text-sm text-muted-foreground mb-3">What your AI says when answering</p>
              <Textarea
                value={config.first_message}
                onChange={(e) => updateConfig({ first_message: e.target.value })}
                className="glass-strong"
                rows={2}
              />
            </div>

            <div>
              <Label className="text-base font-semibold">Speech Recognition</Label>
              <p className="text-sm text-muted-foreground mb-3">How your AI hears customers</p>
              <Select value={config.stt_model} onValueChange={(value) => updateConfig({ stt_model: value })}>
                <SelectTrigger className="glass-strong">
                  <SelectValue placeholder="Select STT" />
                </SelectTrigger>
                <SelectContent>
                  {sttModels.map((m) => (
                    <SelectItem key={m.value} value={m.value}>{m.label} — {m.description}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        )}

        {activeTab === "brain" && (
          <div className="space-y-6">
            <div>
              <Label className="text-base font-semibold">Language Model (LLM)</Label>
              <p className="text-sm text-muted-foreground mb-3">The AI brain powering responses</p>
              <Select value={config.llm_model} onValueChange={(value) => updateConfig({ llm_model: value })}>
                <SelectTrigger className="glass-strong">
                  <SelectValue placeholder="Select LLM" />
                </SelectTrigger>
                <SelectContent>
                  {llmModels.map((m) => (
                    <SelectItem key={m.value} value={m.value}>{m.label} — {m.description}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          </div>
        )}

        {activeTab === "behavior" && (
          <div className="space-y-6">
            <div>
              <Label className="text-base font-semibold">Agent Name</Label>
              <p className="text-sm text-muted-foreground mb-3">What to call your AI</p>
              <Input
                value={config.name}
                onChange={(e) => updateConfig({ name: e.target.value })}
                className="glass-strong"
              />
            </div>

            <div>
              <Label className="text-base font-semibold">System Prompt</Label>
              <p className="text-sm text-muted-foreground mb-3">Instructions that define AI personality</p>
              <Textarea
                value={config.system_prompt}
                onChange={(e) => updateConfig({ system_prompt: e.target.value })}
                className="glass-strong font-mono text-sm"
                rows={10}
              />
            </div>
          </div>
        )}

        {activeTab === "tools" && (
          <div className="space-y-6">
            <p className="text-muted-foreground">Control what your AI can do during calls</p>
            {[
              { key: "check_availability", label: "Check Availability", desc: "Look up open slots" },
              { key: "book_appointment", label: "Book Appointments", desc: "Create bookings" },
              { key: "cancel_appointment", label: "Cancel Appointments", desc: "Cancel bookings" },
              { key: "get_business_info", label: "Business Info", desc: "Answer general questions" },
            ].map((tool) => (
              <div key={tool.key} className="flex items-center justify-between py-3 border-b border-white/10 last:border-0">
                <div>
                  <Label className="text-base">{tool.label}</Label>
                  <p className="text-sm text-muted-foreground">{tool.desc}</p>
                </div>
                <Switch
                  checked={config.tools_config[tool.key as keyof typeof config.tools_config]}
                  onCheckedChange={(checked) => 
                    updateConfig({ tools_config: { ...config.tools_config, [tool.key]: checked } })
                  }
                />
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
